import PulsoLinkCore

/**
 * Near 酒吧聚会门面（对应 Android `BarPartyService`、WEB `hooks/barParty.ts`）：
 * 读走 [BarPartyQueryStore]；写成功后一次 [BarPartyEventBus.invalidate]。
 */
struct BarPartyService: Sendable {
    let repository: BarPartyRepository
    let query: BarPartyQueryStore
    let eventBus: BarPartyEventBus
    let exploreQuery: ExploreQueryStore

    static let rosterPageSize = BarPartyQueryStore.rosterPageSize

    /** 我主持的活动的收款清单，分页；这个运动的任何写操作都会让它重拉。 */
    @MainActor
    func pageHostedChecklists(isAllSettled: Bool) -> PagedList<HostedChecklistRowUi, Int> {
        let repository = repository
        return .offset(invalidates: { eventBus.signals { _ in true } }) { offset, limit in
            let page = try await repository.listHostedPaymentChecklists(
                BarPartyListHostedPaymentChecklistsRequest(offset: offset, limit: limit, isAllSettled: isAllSettled)
            )
            return ListWithTotal(items: page.items.map(HostedChecklistRowUi.init), total: page.total)
        }
    }

    /** 我自己欠的收款行，分页。 */
    @MainActor
    func pageMyPaymentItems(paid: Bool) -> PagedList<MyChecklistItemRowUi, Int> {
        let repository = repository
        return .offset(invalidates: { eventBus.signals { _ in true } }) { offset, limit in
            let page = try await repository.listMyPaymentChecklistItems(
                BarPartyListMyPaymentChecklistItemsRequest(offset: offset, limit: limit, paid: paid)
            )
            return ListWithTotal(items: page.items.map(MyChecklistItemRowUi.init), total: page.total)
        }
    }

    func prefetchDetail(activityId: String) {
        query.prefetchDetail(activityId: activityId)
    }

    func incrementView(activityId: String) async throws -> IncrementBarPartyActivityViewResponse {
        let response = try await repository.incrementBarPartyActivityView(activityId: activityId)
        await query.overlayView(activityId: activityId, view: response.view)
        await exploreQuery.overlayView(activityId: activityId, view: response.view)
        return response
    }

    func create(_ body: CreateBarPartyActivityRequest) async throws -> CreateBarPartyActivityResponse {
        let response = try await repository.createBarPartyActivity(body)
        eventBus.invalidate()
        return response
    }

    func join(activityId: String, _ body: JoinBarPartyActivityRequest = JoinBarPartyActivityRequest()) async throws -> JoinBarPartyActivityResponse {
        let response = try await repository.joinBarPartyActivity(activityId: activityId, body)
        eventBus.invalidate()
        return response
    }

    func getMyRegistrationPayment(activityId: String) async throws -> PaymentHoldActivity {
        try await repository.getMyRegistrationPayment(activityId: activityId)
    }

    func payMyRegistrationPayment(activityId: String, paymentMethodId: String) async throws -> PaymentAttempt {
        let attempt = try await repository.payMyRegistrationPayment(activityId: activityId, PayPaymentRequest(paymentMethodId: paymentMethodId))
        invalidate()
        return attempt
    }

    /** Stripe 付款成功后 webhook 才改报名状态，让订阅方重拉。 */
    func invalidate() {
        eventBus.invalidate()
    }

    func exit(activityId: String) async throws -> BarPartyRegistration {
        let registration = try await repository.exitBarPartyActivity(activityId: activityId)
        eventBus.invalidate()
        return registration
    }

    func end(activityId: String) async throws {
        try await repository.endBarPartyActivity(activityId: activityId)
        eventBus.invalidate()
    }

    func patchBasic(activityId: String, _ body: PatchBarPartyActivityBasicRequest) async throws {
        try await repository.patchBarPartyActivityBasic(activityId: activityId, body)
        eventBus.invalidate()
    }

    func markPaymentItemPaid(itemId: String) async throws {
        try await repository.markPaymentChecklistItemPaid(itemId: itemId)
        eventBus.invalidate()
    }

    func markPaymentItemUnpaid(itemId: String) async throws {
        try await repository.markPaymentChecklistItemUnpaid(itemId: itemId)
        eventBus.invalidate()
    }

    func settleAll(activityId: String) async throws -> BarPartyPaymentChecklistResponse {
        let response = try await repository.settleAllPaymentChecklist(activityId: activityId)
        eventBus.invalidate()
        return response
    }

    func remindItems(activityId: String, itemIds: [String]) async throws {
        try await repository.remindPaymentChecklistItems(activityId: activityId, itemIds: itemIds)
        eventBus.invalidate()
    }
}

extension HostedChecklistRowUi {
    init(_ item: BarPartyHostedPaymentChecklistItem) {
        self.init(
            checklistId: item.id,
            activityId: item.barPartyActivityId,
            title: item.title.isEmpty ? String(item.barPartyActivityId.prefix(8)) : item.title,
            venueName: item.venueName ?? item.address,
            startsAt: item.startsAt,
            isAllSettled: item.isAllSettled
        )
    }
}

extension MyChecklistItemRowUi {
    init(_ item: BarPartyMyPaymentChecklistItem) {
        self.init(
            itemId: item.id,
            activityId: item.barPartyActivityId,
            title: item.title.isEmpty ? String(item.barPartyActivityId.prefix(8)) : item.title,
            venueName: item.venueName ?? item.address,
            startsAt: item.startsAt,
            paid: item.paid,
            priceAmount: item.priceAmount,
            currency: item.currency
        )
    }
}
